insert into public.question_bank (teks_code, teks_item_id, subject, grade_num, course, difficulty, qtype, prompt, choices, answer_idx, explanation, source, status, gen_batch)
select distinct on (v.prompt) v.code, i.id, d.subject,
       case when i.grade_level = 'K' then 0 when i.grade_level ~ '^[0-9]+' then substring(i.grade_level from '^[0-9]+')::smallint end,
       case when i.grade_level is null then i.grade_course_title end,
       v.diff, 'mc', v.prompt, v.choices, v.ans, v.expl, v.src, 'checked', 'hs_eng1_v1'
from (values
('110.36.c.2.A',2,'Which resource would best help a ninth grader confirm the pronunciation and part of speech of the word ''ephemeral''?','["a dictionary", "an atlas", "a thesaurus alone", "an almanac"]'::jsonb,0,'Dictionaries list pronunciation, part of speech and meaning.','original'),
('110.36.c.2.A',3,'A student needs a word that means almost the same as ''brave'' but sounds more formal. Which tool helps most?','["an atlas", "a thesaurus", "a style manual", "a glossary of a science book"]'::jsonb,1,'A thesaurus lists synonyms.','original'),
('110.36.c.2.A',3,'A technical manual includes a section at the back listing specialized terms with definitions. What is it called?','["an index", "an appendix of maps", "a glossary", "a preface"]'::jsonb,2,'A glossary defines key terms from the text.','original'),
('110.36.c.2.B',3,'Which word has the most positive connotation for describing a person who spends carefully?','["miserly", "stingy", "cheap", "thrifty"]'::jsonb,3,'All share the denotation of careful spending, but ''thrifty'' feels positive.','original'),
('110.36.c.2.B',3,'The denotative meaning of a word is what?','["its literal dictionary definition", "the feelings it suggests", "its sound", "its spelling history only"]'::jsonb,0,'Denotation is the literal meaning.','original'),
('110.36.c.2.B',3,'A writer calls a crowd ''a swarm.'' How does this word choice affect the tone compared with ''a gathering''?','["it suggests calm and organized", "it suggests something chaotic and unwelcome", "it suggests silence", "it has no added feeling"]'::jsonb,1,'''Swarm'' connotes insects and disorder.','original'),
('110.36.c.2.B',4,'Which pair shows the same denotation but different connotations?','["hot and cold", "run and sleep", "slim and scrawny", "dog and cat"]'::jsonb,2,'Both describe thinness, but one is kinder.','original'),
('110.36.c.2.C',3,'The phrase ''bona fide'' used in English most nearly means what?','["forbidden", "temporary", "fancy", "genuine"]'::jsonb,3,'From Latin, ''in good faith.''','original'),
('110.36.c.2.C',3,'A writer says a plan has ''carte blanche'' approval. What does the phrase suggest?','["complete freedom to act", "a ban on all action", "a request to wait", "a partial approval"]'::jsonb,0,'From French, ''blank paper.''','original'),
('110.36.c.2.C',3,'What does ''status quo'' refer to?','["a past mistake", "the existing state of affairs", "a rare event", "a future goal"]'::jsonb,1,'Latin for ''the state in which.''','original'),
('110.36.c.2.C',4,'''Ad hoc committee'' means a committee formed for what?','["no particular reason", "a yearly review", "a specific purpose at hand", "permanent service"]'::jsonb,2,'''Ad hoc'' means ''for this.''','original'),
('110.36.c.4.F',3,'Passage: ''Mara checked the clock a fourth time and drummed her fingers on the desk until the bell finally rang.'' What can be inferred about Mara?','["she is deeply interested in the lesson", "she has fallen asleep", "she is the teacher", "she is impatient or anxious for class to end"]'::jsonb,3,'Her repeated clock-checking signals impatience.','original'),
('110.36.c.4.F',3,'Passage: ''The streets were empty, shutters closed, and not a single dog barked.'' What is the best inference?','["something has made the town fearful or quiet", "everyone is on vacation at the beach", "a festival is under way", "it is midday market time"]'::jsonb,0,'The details imply tension or danger.','original'),
('110.36.c.4.F',3,'An inference must be supported by what?','["the author''s biography only", "evidence from the text", "the reader''s mood", "a guess with no basis"]'::jsonb,1,'Strong inferences use details.','original'),
('110.36.c.4.G',3,'Which detail is most likely to reveal the key idea of an informational article?','["the date of publication", "a long quotation of a minor figure", "a claim repeated and developed across several paragraphs", "an aside in one sentence"]'::jsonb,2,'Key ideas are developed throughout.','original'),
('110.36.c.4.G',3,'After reading, you must separate important details from minor ones. What are you doing?','["creating a mental image", "predicting the plot", "making a personal connection", "evaluating details to find key ideas"]'::jsonb,3,'This is the evaluation of details.','original'),
('110.36.c.4.G',4,'In an editorial, the author lists three examples of lost wetland habitat. The key idea they support is most likely what?','["wetland loss is a serious problem", "wetlands are easy to rebuild", "habitats do not matter", "the author dislikes birds"]'::jsonb,0,'Examples back up the central claim.','original'),
('110.36.c.4.H',4,'Text A says a river''s water quality improved after 2005. Text B says fish counts rose after 2005. What new understanding could a reader synthesize?','["the river dried up", "cleaner water may have helped fish populations recover", "fish cause water to be clean", "nothing connects the two"]'::jsonb,1,'Combining two sources suggests a link.','original'),
('110.36.c.4.H',3,'To synthesize information from two texts, a reader should do what?','["summarize only the longer text", "copy one text", "combine ideas from both to form a new understanding", "ignore differences"]'::jsonb,2,'Synthesis builds something new.','original'),
('110.36.c.4.I',2,'A reader loses track of the plot halfway through a chapter. Which strategy fits best?','["memorizing the title", "closing the book for good", "skipping to the end", "re-reading the confusing section"]'::jsonb,3,'Re-reading is a repair strategy.','original'),
('110.36.c.4.I',3,'Which is an example of using background knowledge to repair comprehension?','["recalling what you know about the Great Depression while reading a novel set in 1933", "changing the font", "reading only the first line", "counting the pages"]'::jsonb,0,'Prior knowledge fills gaps.','original'),
('110.36.c.5.B',3,'A student writes a response comparing how two poems treat the theme of loss. Which sentence best shows comparison?','["The first poem is long.", "Both poems explore grief, but the first uses nature imagery while the second uses household objects.", "Poems are written in lines.", "I like poems about loss."]'::jsonb,1,'Comparison names a shared idea and a difference.','original'),
('110.36.c.5.B',3,'Which transition word signals a contrast between two texts?','["similarly", "likewise", "however", "furthermore"]'::jsonb,2,'''However'' marks a difference.','original'),
('110.36.c.5.B',4,'Which thesis best sets up a comparison of two short stories?','["The first story came first.", "Stories are fun to read.", "Both stories are about narrators.", "Though both stories feature a lonely narrator, one resolves isolation through friendship while the other accepts it."]'::jsonb,3,'A strong comparison thesis states a similarity and a difference.','original'),
('110.36.c.5.C',3,'Which is an example of original commentary after a quotation?','["This line shows how the narrator''s guilt grows throughout the scene.", "The narrator says ''I should have stayed.''", "The quote is in quotation marks.", "Page 14 has this line."]'::jsonb,0,'Commentary explains the significance of evidence.','original'),
('110.36.c.5.C',3,'A response includes a quotation but no explanation. What is missing?','["a longer quote", "commentary linking the evidence to the claim", "a title", "more adjectives"]'::jsonb,1,'Evidence must be explained.','original'),
('110.36.c.5.C',3,'Which sentence best introduces a piece of text evidence?','["Quote.", "Here is a quote: ''My hands would not stop shaking.''", "The author emphasizes her fear when she writes, ''My hands would not stop shaking.''", "''My hands would not stop shaking.''"]'::jsonb,2,'A signal phrase connects the evidence to the idea.','original'),
('110.36.c.5.D',3,'Which is the best paraphrase of ''The meeting was adjourned because of the absence of a quorum''?','["Everyone left angry.", "The quorum cancelled the room.", "The meeting was fun and short.", "The meeting ended because not enough members were present."]'::jsonb,3,'A paraphrase keeps meaning in new words.','original'),
('110.36.c.5.D',3,'A good summary of a long article should do what?','["include the main ideas in logical order and in your own words", "include every detail", "add your opinions", "copy every sentence"]'::jsonb,0,'Summaries are brief and faithful.','original'),
('110.36.c.5.D',4,'Which summary sentence introduces a new opinion, making it a poor summary?','["The article lists three advantages.", "The author is clearly wrong about renewable energy.", "The author argues renewable energy can lower costs.", "The author concludes with a call for investment."]'::jsonb,1,'A summary reports; it does not judge.','original'),
('110.36.c.5.F',3,'In a literary response, which word is most precise academic vocabulary for the central message of a story?','["stuff", "thing", "theme", "idea of the part"]'::jsonb,2,'''Theme'' is the standard term.','original'),
('110.36.c.5.F',3,'Which sentence uses academic vocabulary appropriately?','["The author did a thing early on.", "The story had stuff.", "The author put in some hints to be cool.", "The author uses foreshadowing to hint at the conflict."]'::jsonb,3,'Precise terms improve a response.','original'),
('110.36.c.5.G',3,'An explicit meaning in a text is one that is what?','["directly stated", "only implied", "a reader''s guess", "hidden in symbols"]'::jsonb,0,'Explicit means stated plainly.','original')
) as v(code, diff, prompt, choices, ans, expl, src)
join public.teks_items i on i.code = v.code and i.is_standard
join public.teks_documents d on d.id = i.document_id and d.subject = 'English Language Arts and Reading' and d.language = 'en'
on conflict (fingerprint) do nothing;
insert into public.question_bank (teks_code, teks_item_id, subject, grade_num, course, difficulty, qtype, prompt, choices, answer_idx, explanation, source, status, gen_batch)
select distinct on (v.prompt) v.code, i.id, d.subject,
       case when i.grade_level = 'K' then 0 when i.grade_level ~ '^[0-9]+' then substring(i.grade_level from '^[0-9]+')::smallint end,
       case when i.grade_level is null then i.grade_course_title end,
       v.diff, 'mc', v.prompt, v.choices, v.ans, v.expl, v.src, 'checked', 'hs_eng1_v1'
from (values
('110.36.c.5.G',3,'''She slammed the door and did not say goodbye.'' What implicit meaning does this carry?','["she is cheerful", "she is angry", "she is shy", "she is sleepy"]'::jsonb,1,'Actions imply feelings.','original'),
('110.36.c.5.G',4,'A narrator describes a once-lively house as ''quiet as a held breath.'' What is implied?','["the house is newly built", "the house is noisy", "the house feels tense or waiting", "the narrator is moving in"]'::jsonb,2,'The simile suggests suspense.','original'),
('110.36.c.5.J',4,'An author claims ''all teenagers dislike reading,'' citing a survey of 12 students in one class. What is the best challenge?','["the sample was too large", "teenagers never read", "surveys are never valid", "the evidence is too limited to support such a broad claim"]'::jsonb,3,'A hasty generalization from a tiny sample.','original'),
('110.36.c.5.J',3,'To defend an author''s claim, a writer should use what?','["relevant evidence from the text", "a personal anecdote only", "a stronger adjective", "a longer essay"]'::jsonb,0,'Evidence-based defense.','original'),
('110.36.c.5.J',4,'Which response most effectively challenges an author''s claim?','["It says the author is boring", "It identifies a specific weakness and cites text evidence", "It states ''I disagree'' with no reason", "It repeats the author''s claim"]'::jsonb,1,'Support needed.','original'),
('110.36.c.6.A',3,'A character begins greedy but gives away his fortune after a disaster. Which theme is developed?','["money is the most important thing", "disasters never matter", "suffering can change what a person values", "greed is permanent"]'::jsonb,2,'His arc shows change.','original'),
('110.36.c.6.A',3,'How can a plot''s resolution help reveal theme?','["it makes the story shorter", "it introduces new characters only", "it lists the setting", "the outcome suggests the author''s message about the conflict"]'::jsonb,3,'Outcomes carry meaning.','original'),
('110.36.c.6.A',4,'A hero succeeds only after admitting she needs help. Which theme is best supported?','["accepting help can be a strength", "strong people never ask for help", "success is luck", "teamwork is a mistake"]'::jsonb,0,'Her change supports the idea.','original'),
('110.36.c.6.B',3,'Which technique reveals a character''s thoughts directly?','["rhyme scheme", "interior monologue", "foreshadowing", "setting description"]'::jsonb,1,'It shows inner thoughts.','original'),
('110.36.c.6.B',3,'A character is generous but also quick-tempered. What term describes this kind of multi-sided character?','["flat character", "foil", "round character", "stock character"]'::jsonb,2,'Round characters have complexity.','original'),
('110.36.c.6.B',4,'A narrator describes a character only through what others say about him. What type of characterization is this?','["interior monologue", "direct characterization", "omniscient narration", "indirect characterization"]'::jsonb,3,'Traits are shown through others'' views.','original'),
('110.36.c.6.B',3,'A character who contrasts with another to highlight traits is called what?','["a foil", "an epigraph", "a protagonist", "a narrator"]'::jsonb,0,'A foil emphasizes differences.','original'),
('110.36.c.6.C',2,'A scene that jumps back to an earlier event is called what?','["a climax", "a flashback", "a resolution", "foreshadowing"]'::jsonb,1,'It interrupts the timeline.','original'),
('110.36.c.6.C',3,'A narrator mentions a loaded gun in act one that is never used until the ending. This is an example of what?','["a refrain", "irony only", "foreshadowing", "a flashback"]'::jsonb,2,'Early hints suggest later events.','original'),
('110.36.c.6.C',3,'A secondary story that runs alongside the main plot is called what?','["an exposition", "a motif", "a prologue only", "a subplot"]'::jsonb,3,'A subplot adds depth.','original'),
('110.36.c.6.C',4,'Two storylines that echo each other''s events are known as what?','["parallel plots", "an allegory", "a monologue", "a frame story only"]'::jsonb,0,'They mirror one another.','original'),
('110.36.c.6.D',3,'A story set during a long drought explores survival and community. How does the setting influence the theme?','["it supplies the rhyme", "the harsh conditions make cooperation central to the message", "it changes the narrator''s name", "it has no connection"]'::jsonb,1,'Setting shapes meaning.','original'),
('110.36.c.6.D',3,'A novel set in a crowded city emphasizes loneliness. What is the effect of the setting?','["it removes conflict", "it sets the rhythm", "it contrasts crowds with isolation to deepen the theme", "it hides the theme"]'::jsonb,2,'Contrast strengthens meaning.','original'),
('110.36.c.7.A',3,'Which work is a play by William Shakespeare?','["Things Fall Apart", "Pride and Prejudice", "The Great Gatsby", "Romeo and Juliet"]'::jsonb,3,'Shakespeare wrote Romeo and Juliet.','original'),
('110.36.c.7.A',3,'Which novel was written by Chinua Achebe, a Nigerian author?','["Things Fall Apart", "The Odyssey", "To Kill a Mockingbird", "Jane Eyre"]'::jsonb,0,'A landmark African novel.','original'),
('110.36.c.7.A',3,'Which epic poem is attributed to Homer?','["Paradise Lost", "The Odyssey", "Don Quixote", "Beowulf"]'::jsonb,1,'Homer is credited with it.','original'),
('110.36.c.7.A',3,'Which novelist wrote ''To Kill a Mockingbird''?','["Mark Twain", "John Steinbeck", "Harper Lee", "Toni Morrison"]'::jsonb,2,'An American classic.','original'),
('110.36.c.7.B',3,'A poem with fourteen lines and a set rhyme scheme is called what?','["a limerick", "a haiku", "free verse", "a sonnet"]'::jsonb,3,'Sonnets have 14 lines.','original'),
('110.36.c.7.B',3,'What is the term for poetry with no regular rhyme or meter?','["free verse", "an ode", "blank verse", "a ballad"]'::jsonb,0,'No fixed pattern.','original'),
('110.36.c.7.B',4,'Unrhymed lines of iambic pentameter are called what?','["a quatrain", "blank verse", "free verse", "a couplet"]'::jsonb,1,'Common in Shakespeare''s plays.','original'),
('110.36.c.7.B',3,'How many lines are in a quatrain?','["two", "eight", "four", "six"]'::jsonb,2,'A quatrain is a four-line stanza.','original'),
('110.36.c.7.C',3,'In a play, a character speaks alone onstage to reveal inner thoughts. What is this called?','["a stage direction", "an aside to another actor", "a prologue", "a soliloquy"]'::jsonb,3,'A soliloquy is spoken alone.','original'),
('110.36.c.7.C',3,'A short remark to the audience unheard by other characters is called what?','["an aside", "a scene", "an epilogue", "a soliloquy"]'::jsonb,0,'Others onstage do not hear it.','original'),
('110.36.c.7.C',4,'The audience knows a character is in danger but the character does not. This is called what?','["verbal irony", "dramatic irony", "situational irony", "an oxymoron"]'::jsonb,1,'The audience knows more.','original'),
('110.36.c.7.D.i',3,'Which of these is the strongest thesis statement for an expository essay?','["Do you like libraries?", "I will write about libraries.", "Public libraries strengthen communities by offering free access to learning, technology and shared space.", "Libraries are places."]'::jsonb,2,'A thesis states a clear, supportable claim.','original'),
('110.36.c.7.D.i',3,'Where does a conclusion usually restate the thesis?','["in the middle", "in the title only", "before the introduction", "at the end of the essay"]'::jsonb,3,'Conclusions close with the main idea.','original'),
('110.36.c.7.D.ii',3,'An essay explains how a volcano erupts by describing each step in order. What organizational pattern is used?','["chronological order", "spatial order", "compare and contrast", "problem and solution"]'::jsonb,0,'Steps follow a time sequence.','original'),
('110.36.c.7.D.ii',3,'An essay describes a problem of plastic waste and then proposes recycling programs. What pattern is this?','["chronological", "problem and solution", "descriptive only", "cause and effect"]'::jsonb,1,'It states a problem then solutions.','original')
) as v(code, diff, prompt, choices, ans, expl, src)
join public.teks_items i on i.code = v.code and i.is_standard
join public.teks_documents d on d.id = i.document_id and d.subject = 'English Language Arts and Reading' and d.language = 'en'
on conflict (fingerprint) do nothing;
