from (values
('110.36.c.7.E.i',3,'A strong argumentative claim is what?','["a question", "an undeniable fact", "a statement that can be debated and supported", "a quotation"]'::jsonb,2,'Claims must be arguable.','original'),
('110.36.c.7.E.i',3,'Which appeal relies on facts and logic?','["pathos", "kairos only", "ethos", "logos"]'::jsonb,3,'Logos is reason.','original'),
('110.36.c.7.E.ii',3,'In an argument, acknowledging an opposing view and then explaining why it is weaker is called what?','["a rebuttal", "a concession alone", "an anecdote", "a summary"]'::jsonb,0,'A rebuttal answers the counterargument.','original'),
('110.36.c.7.E.ii',4,'A writer says, ''Some argue uniforms limit self-expression; that is true for some, but they also reduce distraction.'' What is the first half of the sentence?','["a thesis", "a concession", "a hook", "a rebuttal"]'::jsonb,1,'A concession grants a point.','original'),
('110.36.c.7.E.iii',3,'Who is an argument''s audience?','["only the writer", "the editor''s family", "the readers the writer hopes to persuade", "the printer"]'::jsonb,2,'Arguments are shaped for readers.','original'),
('110.36.c.7.E.iii',3,'Which tone suits an argument aimed at a school board?','["jokey and slangy", "silent", "angry and insulting", "respectful and formal"]'::jsonb,3,'Audience shapes tone.','original'),
('110.36.c.7.F',3,'Which is a characteristic of a multimodal text?','["it combines words with images, sound or video", "it uses only words", "it has no author", "it cannot be digital"]'::jsonb,0,'Multiple modes work together.','original'),
('110.36.c.7.F',3,'A news website uses an infographic with a video. What does the infographic add?','["a rhyme", "a visual summary of data", "an unrelated advertisement", "a spelling check"]'::jsonb,1,'Visuals convey information.','original'),
('110.36.c.7.F',3,'Which feature helps a reader navigate a website?','["footnotes in a novel", "a stanza break", "hyperlinks and menus", "a glossary of poems"]'::jsonb,2,'Digital texts use navigation tools.','original'),
('110.36.c.8.A',3,'A pamphlet lists symptoms and prevention tips for the flu. What is its most likely purpose?','["to entertain", "to mock", "to sell a novel", "to inform"]'::jsonb,3,'It conveys useful information.','original'),
('110.36.c.8.A',3,'A speech urges voters to approve a new park bond. What is the author''s purpose?','["to persuade", "to give directions", "to entertain with jokes", "to describe a character"]'::jsonb,0,'It seeks to change minds.','original'),
('110.36.c.8.A',4,'A blog written for beginners uses simple terms and avoids jargon. Who is the intended audience?','["lawyers only", "novices", "experts", "professors"]'::jsonb,1,'Language reflects audience.','original'),
('110.36.c.8.B',3,'An article describes how deforestation leads to soil erosion and flooding. What structure is it?','["sequence", "description", "cause and effect", "compare and contrast"]'::jsonb,2,'It links cause to results.','original'),
('110.36.c.8.B',3,'A text lists similarities and differences between two economic systems. What structure is it?','["chronological", "problem and solution", "cause and effect", "compare and contrast"]'::jsonb,3,'It weighs likenesses and differences.','original'),
('110.36.c.8.B',3,'A history chapter lists events in the order they occurred. What structure is it?','["chronological", "spatial", "order of importance", "compare and contrast"]'::jsonb,0,'Time order.','original'),
('110.36.c.8.C',3,'Why might an author use bold headings in an article?','["to make the text harder to read", "to help readers locate and organize sections", "to hide the main idea", "to lengthen it"]'::jsonb,1,'Headings guide readers.','original'),
('110.36.c.8.C',3,'A bar graph accompanies a paragraph on rising temperatures. What purpose does the graph serve?','["it replaces all text", "it contradicts the text", "it presents data clearly to support the text", "it is decoration"]'::jsonb,2,'Graphics support claims.','original'),
('110.36.c.8.C',3,'Italicized terms followed by definitions in a textbook help readers do what?','["find the author''s name", "skip the chapter", "count the pages", "learn key vocabulary"]'::jsonb,3,'Print features signal terms.','original'),
('110.36.c.8.D',3,'A writer compares a city at night to ''a jewelry box spilled open.'' What does this language achieve?','["it creates a vivid, glittering image", "it lists directions", "it states a statistic", "it avoids imagery"]'::jsonb,0,'Figurative language paints a picture.','original'),
('110.36.c.8.D',3,'Why might an author repeat a phrase at the start of successive sentences?','["to confuse readers", "to emphasize an idea and build rhythm", "to hide meaning", "to save space"]'::jsonb,1,'Repetition builds emphasis.','original'),
('110.36.c.8.D',4,'A speaker uses the phrase ''we shall'' repeatedly. What effect is likely?','["doubt", "a casual tone", "a powerful, determined rhythm", "humor"]'::jsonb,2,'Anaphora strengthens resolve.','original'),
('110.36.c.8.E',3,'A fire station burns down. What kind of irony is this?','["verbal irony", "dramatic irony", "an oxymoron", "situational irony"]'::jsonb,3,'The outcome contradicts expectations.','original'),
('110.36.c.8.E',3,'Which phrase is an oxymoron?','["deafening silence", "a quiet room", "bright light", "very loud noise"]'::jsonb,0,'It combines opposites.','original'),
('110.36.c.8.E',3,'Someone says ''What lovely weather!'' during a storm. What is this?','["alliteration", "verbal irony", "situational irony", "dramatic irony"]'::jsonb,1,'The speaker means the opposite.','original'),
('110.36.c.8.E',3,'Which pair is an oxymoron?','["red roses", "sweet and sour candy", "bittersweet", "sour milk"]'::jsonb,2,'A single term merging opposites.','original'),
('110.36.c.8.F',3,'An author uses short, choppy sentences during a chase scene. What effect does the syntax have?','["it adds humor", "it slows the pace", "it creates calm", "it creates urgency and tension"]'::jsonb,3,'Short sentences speed the pace.','original'),
('110.36.c.8.F',3,'Formal diction in a narrator''s voice creates what effect?','["a serious, dignified tone", "no tone", "a casual tone", "a silly tone"]'::jsonb,0,'Word choice shapes tone.','original'),
('110.36.c.8.F',4,'Long, flowing sentences with many clauses most often suggest what mood?','["panicked", "reflective or contemplative", "abrupt", "comedic"]'::jsonb,1,'Syntax slows the reader.','original'),
('110.36.c.8.G',3,'Saying ''It''s just a scratch'' about a deep wound is an example of what?','["overstatement", "personification", "understatement", "simile"]'::jsonb,2,'Minimizing seriousness.','original'),
('110.36.c.8.G',3,'''I''ve told you a million times'' is an example of what?','["an oxymoron", "irony", "understatement", "overstatement (hyperbole)"]'::jsonb,3,'Exaggeration for emphasis.','original'),
('110.36.c.8.G',4,'Why might a speaker use understatement?','["to create irony or emphasize by contrast", "to avoid meaning", "to lengthen a speech", "to confuse listeners"]'::jsonb,0,'It can heighten an effect.','original'),
('110.36.c.9.B.i',3,'Which structure fits an essay on the causes of the Dust Bowl?','["poem form", "cause and effect", "alphabetical", "random"]'::jsonb,1,'Match structure to purpose.','original'),
('110.36.c.9.B.i',3,'What is the role of a topic sentence?','["to end the essay", "to ask for feedback", "to state the main idea of a paragraph", "to list sources"]'::jsonb,2,'It anchors the paragraph.','original')
) as v(code, diff, prompt, choices, ans, expl, src)
join public.teks_items i on i.code = v.code and i.is_standard
join public.teks_documents d on d.id = i.document_id and d.subject = 'English Language Arts and Reading' and d.language = 'en'
on conflict (fingerprint) do nothing;
insert into public.question_bank (teks_code, teks_item_id, subject, grade_num, course, difficulty, qtype, prompt, choices, answer_idx, explanation, source, status, gen_batch)
select distinct on (v.prompt) v.code, i.id, d.subject,
       case when i.grade_level = 'K' then 0 when i.grade_level ~ '^[0-9]+' then substring(i.grade_level from '^[0-9]+')::smallint end,
       case when i.grade_level is null then i.grade_course_title end,
       v.diff, 'mc', v.prompt, v.choices, v.ans, v.expl, v.src, 'checked', 'hs_eng1_v1'
from (values
('110.36.c.9.B.ii',3,'Which detail best develops the idea that a town is friendly?','["It is a place.", "People live there.", "The town has a street.", "Neighbors waved from porches and brought casseroles to every new family."]'::jsonb,3,'Specific details show depth.','original'),
('110.36.c.9.B.ii',3,'What does adding a concrete example do for an idea?','["makes it clearer and more convincing", "adds confusion", "shortens the essay", "removes the thesis"]'::jsonb,0,'Examples strengthen development.','original'),
('110.36.c.9.C',3,'A student combines three short, choppy sentences into one smooth sentence. What aspect of writing is improved?','["spelling", "sentence variety and flow", "title", "citations"]'::jsonb,1,'Revision improves style.','original'),
('110.36.c.9.C',3,'Replacing ''good'' with ''dependable'' is mainly a revision of what?','["capitalization", "punctuation", "diction (word choice)", "paragraphing"]'::jsonb,2,'More precise words.','original'),
('110.36.c.9.C',3,'Moving a paragraph so ideas follow a logical order improves what?','["vocabulary", "handwriting", "spelling", "organization"]'::jsonb,3,'Reordering helps clarity.','original'),
('110.36.c.9.D.i',3,'Which sentence contains a comma splice?','["The test was hard, I studied for it.", "The test was hard, but I studied for it.", "I studied for the hard test.", "The test was hard; I studied for it."]'::jsonb,0,'A comma alone cannot join independent clauses.','original'),
('110.36.c.9.D.ii',3,'Which sentence has consistent verb tense?','["She opens the box and found a map.", "She opened the box and found a map.", "She open the box and finding a map.", "She opened the box and finds a map."]'::jsonb,1,'Both verbs are past tense.','original'),
('110.36.c.9.D.iii',3,'Which pronoun best completes: ''The committee announced ____ decision.''','["theirs", "it''s", "its", "their own and its"]'::jsonb,2,'A committee acts as a single unit.','original'),
('110.36.c.9.D.iv',2,'In the sentence ''my aunt lives in houston,'' which words need capital letters?','["my and aunt", "lives and in", "aunt and lives", "my and houston"]'::jsonb,3,'Capitalize the first word and proper nouns.','original'),
('110.36.c.9.D.iv',3,'In standard title capitalization, which kind of word is normally left lowercase in the middle of a title?','["short conjunctions and prepositions", "nouns", "verbs", "adjectives"]'::jsonb,0,'Major words are capitalized.','original'),
('110.36.c.9.D.v',3,'Which sentence uses dashes correctly to set off a phrase?','["My brother—who loves chess won—the tournament.", "My brother—who loves chess—won the tournament.", "My brother who—loves chess won the—tournament.", "My—brother who loves chess won the tournament."]'::jsonb,1,'Dashes enclose an interruption.','original'),
('110.36.c.9.D.vi',3,'Which sentence uses the correct word?','["The principal gave the principal of fairness.", "The principle gave the principle of fairness.", "The principal gave the principle of fairness as her reason.", "The principle gave the principal of fairness as her reason."]'::jsonb,2,'Principal is a person; principle is a rule.','original'),
('110.36.c.10.D',3,'Which closing is appropriate for a formal business letter?','["Peace out,", "Your pal,", "Later!", "Sincerely,"]'::jsonb,3,'Formal letters use formal closings.','original'),
('110.36.c.10.D',3,'Which greeting suits a formal letter to an unknown hiring manager?','["Dear Hiring Manager:", "What''s up,", "Yo,", "Hey you,"]'::jsonb,0,'Formal greeting with a colon.','original'),
('110.36.c.11.E',3,'Which source is most likely to give reliable information about a historical event?','["an anonymous social media post", "a peer-reviewed history journal", "a personal blog with no citations", "a satirical website"]'::jsonb,1,'Scholarly sources are vetted.','original'),
('110.36.c.11.E',3,'A library database is useful for locating what?','["only novels", "only maps", "published articles and reference materials", "phone numbers"]'::jsonb,2,'Databases index sources.','original'),
('110.36.c.11.F',3,'To synthesize information from several sources, a researcher should do what?','["list sources only", "avoid comparing them", "copy one source", "combine ideas into one coherent understanding with attribution"]'::jsonb,3,'Synthesis merges and credits ideas.','original'),
('110.36.c.11.H',3,'Why do writers cite sources?','["to give credit and let readers find the original", "to hide the author", "to make the paper longer", "to confuse readers"]'::jsonb,0,'Citations avoid plagiarism.','original'),
('110.36.c.11.H',3,'Presenting someone else''s wording as your own without credit is called what?','["summarizing", "plagiarism", "paraphrasing", "annotating"]'::jsonb,1,'It is a serious academic offense.','original'),
('110.36.c.11.G.i',3,'Which clue suggests a source may be biased?','["it lists a date", "it cites several experts", "it uses loaded language and omits opposing evidence", "it includes data tables"]'::jsonb,2,'Omission and slant signal bias.','original'),
('110.36.c.11.G.i',3,'Which author is most credible on climate science?','["an anonymous commenter", "a celebrity with no training", "a company selling a product", "a climate scientist at a university"]'::jsonb,3,'Expertise improves credibility.','original'),
('110.36.c.11.G.ii',3,'Saying ''You can''t trust his argument because he failed math'' is which fallacy?','["ad hominem", "false dilemma", "bandwagon", "slippery slope"]'::jsonb,0,'It attacks the person, not the argument.','original'),
('110.36.c.11.G.ii',3,'''If we allow this rule, soon there will be no rules at all'' is an example of what?','["appeal to authority", "slippery slope", "ad hominem", "circular reasoning"]'::jsonb,1,'It predicts an extreme chain without proof.','original'),
('110.36.c.11.G.ii',4,'A headline calls a policy ''a disastrous, reckless scheme'' without evidence. Which problem is this?','["a statistic", "a citation", "loaded language", "a balanced tone"]'::jsonb,2,'Emotional words replace evidence.','original')
) as v(code, diff, prompt, choices, ans, expl, src)
join public.teks_items i on i.code = v.code and i.is_standard
join public.teks_documents d on d.id = i.document_id and d.subject = 'English Language Arts and Reading' and d.language = 'en'
on conflict (fingerprint) do nothing;
